#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void normalize_path(char* file) {
    if (file == NULL) {
        return;
    }

    size_t len = strlen(file);
    if (len == 0) {
        return;
    }

    // Allocate a buffer to hold the normalized path
    char* normalized = (char*)malloc(len + 1);
    if (normalized == NULL) {
        return; // Memory allocation failed
    }

    char* dest = normalized;
    const char* src = file;

    // Skip leading './'
    while (*src == '.' && src[1] == '/') {
        src += 2;
    }

    // Process the rest of the path
    while (*src != '\0') {
        if (*src == '/') {
            // Skip consecutive slashes
            while (*src == '/') {
                src++;
            }
            // Add a single slash to the result
            *dest++ = '/';
        } else if (*src == '.' && src[1] == '.' && (src[2] == '/' || src[2] == '\0')) {
            // Handle '..' (but don't go beyond the start of the path)
            if (dest > normalized + 1 && *(dest - 2) == '/') {
                // Remove the last directory from the result
                while (dest > normalized && *(dest - 1) != '/') {
                    dest--;
                }
            }
            src += 3; // Skip '../'
        } else {
            // Copy normal character
            *dest++ = *src++;
        }
    }

    // Eliminate trailing '/..'
    if (dest > normalized && *(dest - 1) == '/' && dest - normalized >= 3 && *(dest - 3) == '.' && *(dest - 2) == '.' && *(dest - 1) == '/') {
        dest -= 3;
    }

    // Null-terminate the normalized path
    *dest = '\0';

    // Copy the normalized path back to the original buffer
    strcpy(file, normalized);

    // Free the allocated memory
    free(normalized);
}
